use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SvgIcon {
    pub asset_id: String,
    pub svg: String,
}

impl SvgIcon {
    pub fn new(asset_id: impl Into<String>, svg: impl Into<String>) -> Self {
        Self {
            asset_id: asset_id.into(),
            svg: svg.into(),
        }
    }

    fn missing(asset_id: impl Into<String>) -> Self {
        Self::new(
            asset_id,
            r#"<svg xmlns="http://www.w3.org/2000/svg" data-kcu-icon="missing" viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18" fill="none" stroke="currentColor" stroke-width="2"/></svg>"#,
        )
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct IconRegistry {
    icons: BTreeMap<String, SvgIcon>,
}

impl IconRegistry {
    pub fn override_icon(&mut self, icon: SvgIcon) {
        self.icons.insert(icon.asset_id.clone(), icon);
    }

    pub fn resolve(&self, asset_id: &str) -> SvgIcon {
        if let Some(icon) = self.icons.get(asset_id) {
            return icon.clone();
        }
        SvgIcon::missing(asset_id)
    }

    fn with_defaults() -> Self {
        let mut registry = Self {
            icons: BTreeMap::new(),
        };
        registry.override_icon(SvgIcon::new("send", SEND_ICON));
        registry.override_icon(SvgIcon::new("stop", STOP_ICON));
        registry.override_icon(SvgIcon::new("attach", ATTACH_ICON));
        registry.override_icon(SvgIcon::new("new-chat", NEW_CHAT_ICON));
        registry.override_icon(SvgIcon::new("history", HISTORY_ICON));
        registry.override_icon(SvgIcon::new("settings", SETTINGS_ICON));
        registry.override_icon(SvgIcon::new("provider:ollama", OLLAMA_PROVIDER_ICON));
        registry.override_icon(SvgIcon::new(
            "provider:claude-code",
            CLAUDE_CODE_PROVIDER_ICON,
        ));
        registry.override_icon(SvgIcon::new("provider:codex-cli", CODEX_PROVIDER_ICON));
        registry.override_icon(SvgIcon::new(
            "provider:github-copilot",
            GITHUB_COPILOT_PROVIDER_ICON,
        ));
        registry.override_icon(SvgIcon::new("provider:opencode", OPENCODE_PROVIDER_ICON));
        registry
    }
}

